"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[19936],{28453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var o=n(96540);const a={},i=o.createContext(a);function s(e){const t=o.useContext(i);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:t},e.children)}},31790:(e,t,n)=>{n.d(t,{Ay:()=>l,RM:()=>s});var o=n(74848),a=n(28453),i=n(86025);const s=[];function r(e){const t={admonition:"admonition",blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"stock-market-chitchat-g-shares-are-the-g-spot-and-you-dont-need-protection-in-a-big-bull-market",children:"Stock Market Chitchat: G-Shares Are the G-Spot, and You Don't Need Protection in a Big Bull Market!"})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"2006/5/12 19:02:25"}),"\n"]}),"\n",(0,o.jsx)(t.admonition,{title:"Reader-contributed images, please verify independently",type:"warning",children:(0,o.jsx)("div",{style:{textAlign:"left"},children:(0,o.jsx)("img",{src:(0,i.Ay)("/img/stocks/stockschat/1.png"),style:{marginTop:"15px",width:880}})})}),"\n",(0,o.jsx)(t.p,{children:"Anyone who can actually chat about the stock market with this ID \u2014 if such a person exists \u2014 is at most in the sperm or egg stage, not even a fertilized egg yet. Moreover, this stock market game is made by doing, not talking, so generally I don't discuss it. But seeing how some people have been tormented so badly by this market, and it being the weekend, out of sympathy, let me say a few words."}),"\n",(0,o.jsx)(t.p,{children:'A year ago, when the market plummeted to 1,000 points in its bloodiest storm, I saw many pitiful people online at the time. Using my old ID, I gave one clear pronouncement: "G-Shares Are the G-Spot" \u2014 the bloodier and stormier it gets, the greater the opportunity. Now this G-spot has been worked to the point where many people can\'t take it anymore. The overwhelming majority of market participants are quite pathetic \u2014 afraid when it falls, afraid when it rises, truly pitiable. For this reason, today I\'ll offer another saying: "You Don\'t Need Protection in a Big Bull Market."'}),"\n",(0,o.jsx)(t.p,{children:"The key meaning of \"not needing protection\" here is: don't apply old frameworks to forecast market movements, especially for those who don't know the market well. For example, the other day I saw someone complaining that the Wuliangye warrants had gone crazy, already at 3 or 4 yuan. These people simply don't understand the market well enough. Do you know how high the Bao'an warrants were pushed back in the day? Do you know that the Shenzhen market, influenced by Hong Kong, has always had a tradition of speculating on warrants? Do you know that in Hong Kong, warrants far crazier than this are everywhere? The market will always surpass ordinary people's imagination. Three or four yuan is expensive? Why can't a stock price be more expensive than the liquor it represents? What would be so strange about the day when \u2014 on a cum-rights basis \u2014 a bottle of Maotai or Wuliangye can't buy a single share of the corresponding stock?"}),"\n",(0,o.jsx)(t.admonition,{title:"Reader-contributed images, please verify independently",type:"warning",children:(0,o.jsx)("div",{style:{textAlign:"left"},children:(0,o.jsx)("img",{src:(0,i.Ay)("/img/stocks/stockschat/2.png"),style:{marginTop:"15px",width:600}})})}),"\n",(0,o.jsx)(t.p,{children:"Of course, for the very few, the market is simply an ATM \u2014 withdraw whenever you want. How can this be achieved? By thoroughly understanding the market. Those who truly understand the market know that all markets are the same \u2014 like people wearing different clothes, strip them bare and they're all identical. Those who truly understand the market don't care about bull or bear \u2014 the market is always an ATM. Of course, if the market can only be unidirectional, the only difference is that during bear markets, the amount of capital deployed and the frequency of swings should be smaller."}),"\n",(0,o.jsx)(t.p,{children:"However, even in a bull market, the difference in profit levels between masters and novices is enormous. If a stock doubles, the most a novice can pocket is a 100% gain, while a master can easily turn it into 300% or 400%. In fact, stock investing is very simple. The most critical factor is cost, and timing is essentially cost. If you have the ability to keep your cost below the market's average cost, you will always be in an invincible position. Since fluctuation is where market risk lies, it correspondingly provides the opportunity to exploit market risk, to use every worthwhile fluctuation to drive your holding cost down to zero or even negative. This way, regardless of bull or bear markets, nothing matters. Where there's fluctuation, there's risk, and correspondingly there's profit. For a master, given enough time, the profit squeezed from a declining stock will certainly exceed what a novice can extract from a rising stock. Of course, this is just an illustration \u2014 a true master would never deliberately trade against the trend."}),"\n",(0,o.jsx)(t.p,{children:"Investing is an art, and the art of investing ultimately comes down to the art of capital management \u2014 just as the art of singing ultimately comes down to the art of breathing. And market fluctuations ultimately unfold within a complete classification formed by the relationship between consecutive highs and lows. Once you understand this, the market becomes as readily visible as the lines on your own palm. All of the above applies not just to retail investors but equally to market makers. Those who understand this can navigate the market with ease. Of course, beyond this level, there is a higher path \u2014 but that's not something to be discussed with ordinary people, and even if I did, it would be pointless, so I won't."})]})}function l(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(r,{...e})}):r(e)}},63811:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"timeline/economics/stockschat","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/economics/stockschat.md","sourceDirName":"timeline/economics","slug":"/timeline/economics/stockschat","permalink":"/en/timeline/economics/stockschat","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"stockschat","title":"","hide_table_of_contents":true},"sidebar":"timelineSidebar","previous":{"title":"\u7537\u6027\u670d\u52a1\u8005\u4e0d\u80fd\u5b8c\u6210\u670d\u52a1\u662f\u5426\u6709\u8d44\u683c\u6536\u8d39\uff1f (2006/5/11 22:07:26)","permalink":"/en/timeline/essays/malesexworkers"},"next":{"title":"\u623f\u5974\uff0c\u81ea\u5df1\u50bb\u8fd8\u51fa\u6765\u73b0\u773c\uff0c\u4e22\u4eba\u4e0d\uff1f\uff01 (2006/5/13 18:30:03)","permalink":"/en/timeline/economics/houseslave"}}');var a=n(74848),i=n(28453),s=n(31790);const r={id:"stockschat",title:"",hide_table_of_contents:!0},l=void 0,h={},c=[...s.RM];function d(e){return(0,a.jsx)(s.Ay,{})}function u(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d()}}}]);